mapper.select:
select pr.id as personal_registration_id, pr.season_id, se.display_title as season_title, pr.division_id, d.division_name, d.platform_code, pr.player_id, coalesce(p.game_nickname, mp.nickname) as player_name, pr.actual_platform_code, pr.preferred_position, pr.registration_status, pr.submit_time, pr.approved_time, pr.reject_reason from basket_personal_registration pr left join basket_season se on se.id = pr.season_id and se.is_delete = 0 left join basket_division d on d.id = pr.division_id and d.is_delete = 0 left join basket_player_profile p on p.id = pr.player_id and p.is_delete = 0 left join basket_member_profile mp on mp.member_id = p.member_id and mp.is_delete = 0 where pr.is_delete = 0 and pr.season_id = #{seasonId} and pr.division_id = #{divisionId} and pr.registration_status = #{registrationStatus}
and coalesce(p.game_nickname, mp.nickname) like concat('%', #{playerName}, '%')
order by case when pr.registration_status = 'PENDING_REVIEW' then 0 else 1 end, pr.submit_time desc, pr.id desc

mapper.insert:
insert into basket_personal_registration (
    division_id, season_id, series_id, user_id, player_id, player_platform_id, actual_platform_code, game_account_id, preferred_position, registration_status, submit_time, approved_time, reject_reason, assigned_draw_team_id, converted_registration_id, active_unique_key, create_by, update_by, create_time, update_time, is_delete
) values (
    #{divisionId}, #{seasonId}, #{seriesId}, #{userId}, #{playerId}, #{playerPlatformId}, #{actualPlatformCode}, #{gameAccountId}, #{preferredPosition}, #{registrationStatus}, #{submitTime}, #{approvedTime}, #{rejectReason}, #{assignedDrawTeamId}, #{convertedRegistrationId}, #{activeUniqueKey}, #{createBy}, #{updateBy}, #{createTime}, #{updateTime}, #{isDelete}
)
